public sealed class Downloader
{
    public Task<string> GetAsync(Uri uri, IProgress<double>? progress = null,
                                 CancellationToken ct = default) => /* ... */;

    // callback-shaped completion over an asynchronous operation
    public void Get(Uri uri, Action<string> onDone, Action<Exception> onError) =>
        GetAsync(uri).ContinueWith(t =>
        {
            if (t.IsFaulted) onError(t.Exception!);
            else onDone(t.Result);
        }, TaskScheduler.Default);
}
